  const serverHistory = trpc.functional.history.useQuery(historyInput, { enabled: Boolean(selectedServer?.id) });
  const selectedMaster = selectedServer as (typeof selectedServer & { setor?: string | null; categoria?: string; telefone?: string; emailInstitucional?: string; emailPessoal?: string; cpf?: string; rg?: string; dataNascimento?: Date | string | null; dataContratacao?: Date | string | null; dataTerminoVigencia?: Date | string | null; participarComemoracao?: "Sim" | "Não" | null; motivoNaoParticipar?: string | null; docenteClasse?: string | null; docenteNivel?: string | null; tecnicoNivel?: number | null; grau?: number | null; referencia?: number | null; estagiarioCalculaVigencia?: "Sim" | "Não" | null; contagemRenovacao?: number | null; terceirizadoSubstituto?: "Sim" | "Não" | null; idServidorSubstituido?: number | null; cargoComissionado?: string | null; substitutoComissionado?: string | null; portariaSubstituicao?: string | null });
